/* ============================================
   Volta Studio — Corporate Website Styles
   Minimal, Editorial, Warm
   ============================================ */

/* --- Google Fonts --- */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;0,800;1,400;1,500;1,600&family=Inter:wght@300;400;500;600&display=swap');

/* --- CSS Custom Properties --- */
:root {
  --bg: #F5F2ED;
  --bg-alt: #EDE9E3;
  --text: #1A1A1A;
  --text-light: #6B6560;
  --accent-terracotta: #C4704B;
  --accent-sage: #8B9E7E;
  --accent-sand: #C9B99A;
  --accent-warm: #A68A7B;
  --serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --max-width: 1400px;
  --reading-width: 680px;
  --nav-height: 72px;
}

/* --- Reset --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--sans);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.7;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--serif);
  font-weight: 500;
  line-height: 1.15;
}

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  height: var(--nav-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 48px;
  background: var(--bg);
  transition: background 0.3s ease;
}

.nav-logo {
  font-family: var(--serif);
  font-size: 1.35rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.nav-links {
  display: flex;
  gap: 36px;
  list-style: none;
}

.nav-links a {
  font-size: 0.85rem;
  font-weight: 400;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  transition: opacity 0.2s ease;
}

.nav-links a:hover {
  opacity: 0.5;
}

.nav-links a.active {
  opacity: 0.4;
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 32px;
  height: 32px;
  cursor: pointer;
  background: none;
  border: none;
  z-index: 110;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 1.5px;
  background: var(--text);
  transition: all 0.3s ease;
  position: absolute;
}

.hamburger span:first-child {
  transform: translateY(-6px);
}

.hamburger span:last-child {
  transform: translateY(6px);
}

.hamburger.active span:first-child {
  transform: rotate(45deg);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:last-child {
  transform: rotate(-45deg);
}

/* Mobile Menu Overlay */
.mobile-menu {
  position: fixed;
  inset: 0;
  z-index: 105;
  background: var(--bg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 32px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-menu.active {
  opacity: 1;
  pointer-events: all;
}

.mobile-menu a {
  font-family: var(--serif);
  font-size: 2.5rem;
  font-weight: 500;
  transition: opacity 0.2s ease;
}

.mobile-menu a:hover {
  opacity: 0.5;
}

/* --- Hero --- */
.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: calc(var(--nav-height) + 60px) 48px 80px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.hero h1 {
  font-size: clamp(2.8rem, 6vw, 5.5rem);
  font-weight: 500;
  letter-spacing: -0.03em;
  max-width: 900px;
  line-height: 1.08;
}

/* --- Media Showcase (Triptych) --- */
.media-showcase {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 16px;
  padding: 0 48px 100px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.media-block {
  aspect-ratio: 3/4;
  border-radius: 4px;
  overflow: hidden;
}

.media-block:nth-child(1) {
  background-color: var(--accent-terracotta);
}

.media-block:nth-child(2) {
  background-color: var(--accent-sage);
  margin-top: 40px;
}

.media-block:nth-child(3) {
  background-color: var(--accent-sand);
}

/* --- Client Marquee --- */
.marquee-section {
  padding: 60px 0 100px;
  overflow: hidden;
  border-top: 1px solid rgba(26, 26, 26, 0.08);
}

.marquee-row {
  display: flex;
  white-space: nowrap;
  margin-bottom: 12px;
}

.marquee-row:last-child {
  margin-bottom: 0;
}

.marquee-track {
  display: flex;
  animation: marquee-scroll 30s linear infinite;
  will-change: transform;
}

.marquee-row:nth-child(2) .marquee-track {
  animation-direction: reverse;
  animation-duration: 35s;
}

.marquee-row:nth-child(3) .marquee-track {
  animation-duration: 28s;
}

.marquee-item {
  font-family: var(--serif);
  font-size: clamp(1.8rem, 3.5vw, 3.2rem);
  font-weight: 500;
  letter-spacing: -0.01em;
  padding: 0 24px;
  opacity: 0.85;
  flex-shrink: 0;
}

.marquee-item .dot {
  display: inline-block;
  margin: 0 24px;
  opacity: 0.3;
  font-size: 0.6em;
  vertical-align: middle;
}

@keyframes marquee-scroll {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(-50%);
  }
}

/* --- About Section --- */
.about-section {
  padding: 100px 48px;
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 80px;
  align-items: start;
}

.about-label {
  font-size: 0.8rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-light);
}

.about-text p {
  font-size: 1.15rem;
  line-height: 1.8;
  margin-bottom: 28px;
  color: var(--text);
}

.about-text p:last-child {
  margin-bottom: 0;
}

/* --- Founder Letter (neweno.html) --- */
.founder-letter {
  padding: calc(var(--nav-height) + 80px) 48px 120px;
  max-width: var(--reading-width);
  margin: 0 auto;
}

.founder-letter-header {
  margin-bottom: 60px;
}

.founder-letter-header .page-label {
  font-size: 0.8rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-light);
  margin-bottom: 32px;
}

.founder-letter h1 {
  font-size: clamp(2.2rem, 4vw, 3.5rem);
  font-weight: 500;
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.founder-letter-content p {
  font-size: 1.1rem;
  line-height: 1.9;
  margin-bottom: 28px;
}

.founder-letter-content p:last-child {
  margin-bottom: 0;
}

.founder-letter-content .signature {
  font-family: var(--serif);
  font-style: italic;
  font-size: 1.3rem;
  margin-top: 48px;
  color: var(--text-light);
}

/* --- Services Page --- */
.services-page {
  padding: calc(var(--nav-height) + 80px) 48px 120px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.philosophy-section {
  max-width: 800px;
  margin-bottom: 100px;
}

.philosophy-section .page-label {
  font-size: 0.8rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-light);
  margin-bottom: 32px;
}

.philosophy-section h1 {
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  font-weight: 500;
  letter-spacing: -0.03em;
  margin-bottom: 32px;
}

.philosophy-section p {
  font-size: 1.15rem;
  line-height: 1.85;
  margin-bottom: 24px;
}

.divider {
  width: 100%;
  height: 1px;
  background: rgba(26, 26, 26, 0.12);
  margin: 80px 0;
}

.services-details {
  max-width: 900px;
}

.services-details h2 {
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  font-weight: 500;
  letter-spacing: -0.02em;
  margin-bottom: 60px;
}

.service-item {
  margin-bottom: 64px;
}

.service-item:last-child {
  margin-bottom: 0;
}

.service-item h3 {
  font-size: 1.6rem;
  font-weight: 600;
  margin-bottom: 16px;
  letter-spacing: -0.01em;
}

.service-item p {
  font-size: 1.05rem;
  line-height: 1.85;
  color: var(--text-light);
}

/* --- Clients Page --- */
.clients-page {
  padding: calc(var(--nav-height) + 80px) 48px 120px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.clients-heading {
  margin-bottom: 80px;
}

.clients-heading .page-label {
  font-size: 0.8rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-light);
  margin-bottom: 24px;
}

.clients-heading h1 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 500;
  letter-spacing: -0.03em;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 48px 64px;
}

.client-card h3 {
  font-family: var(--serif);
  font-size: 1.3rem;
  font-weight: 600;
  margin-bottom: 10px;
  letter-spacing: -0.01em;
}

.client-card p {
  font-size: 0.92rem;
  line-height: 1.7;
  color: var(--text-light);
}

/* --- Contact Page --- */
.contact-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: calc(var(--nav-height) + 40px) 48px 80px;
  text-align: center;
}

.contact-page h1 {
  font-size: clamp(5rem, 15vw, 14rem);
  font-weight: 500;
  letter-spacing: -0.04em;
  line-height: 0.9;
  margin-bottom: 60px;
}

.contact-links {
  display: flex;
  gap: 48px;
  list-style: none;
}

.contact-links a {
  font-family: var(--serif);
  font-size: 1.2rem;
  font-weight: 500;
  position: relative;
  transition: opacity 0.2s ease;
}

.contact-links a:hover {
  opacity: 0.5;
}

/* --- Footer --- */
.footer {
  padding: 40px 48px;
  border-top: 1px solid rgba(26, 26, 26, 0.08);
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer span {
  font-size: 0.8rem;
  color: var(--text-light);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .about-section {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 36px 48px;
  }
}

@media (max-width: 768px) {
  .nav {
    padding: 0 24px;
  }

  .nav-links {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    padding: calc(var(--nav-height) + 40px) 24px 60px;
  }

  .hero h1 {
    font-size: clamp(2rem, 8vw, 3rem);
  }

  .media-showcase {
    grid-template-columns: 1fr;
    gap: 12px;
    padding: 0 24px 80px;
  }

  .media-block:nth-child(2) {
    margin-top: 0;
  }

  .media-block {
    aspect-ratio: 4/3;
  }

  .marquee-section {
    padding: 40px 0 80px;
  }

  .about-section {
    padding: 80px 24px;
  }

  .founder-letter {
    padding: calc(var(--nav-height) + 48px) 24px 80px;
  }

  .services-page {
    padding: calc(var(--nav-height) + 48px) 24px 80px;
  }

  .clients-page {
    padding: calc(var(--nav-height) + 48px) 24px 80px;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 36px;
  }

  .contact-page h1 {
    font-size: clamp(3.5rem, 18vw, 7rem);
    margin-bottom: 48px;
  }

  .contact-links {
    flex-direction: column;
    gap: 24px;
  }

  .footer {
    padding: 32px 24px;
    flex-direction: column;
    gap: 8px;
    text-align: center;
  }

  .divider {
    margin: 60px 0;
  }

  .philosophy-section {
    margin-bottom: 80px;
  }
}

